// Package bindmodel holds the binding round-trips' entity: Bind, with a field
// of every column type the migration planner writes. It is generated by
// velox-gen from the DSL schema in the schema directory:
//
//	go build -o bin/velox-gen ./cmd/velox-gen && bin/velox-gen -out internal/bindmodel -package bindmodel ./internal/bindmodel/schema
//
// Its table is made by the planner, not by hand: the itests plan it from the
// schema and apply it with migrate.Up.
package bindmodel
